final class Order {
  private Status status = Status.DRAFT;

  void pay(PaymentReceipt receipt) {
    if (status != Status.DRAFT) throw new IllegalStateException("order is not payable");
    if (!receipt.covers(this)) throw new IllegalArgumentException("amount mismatch");
    status = Status.PAID;
  }
}

